function MillstoneCraneWinchMaker.init() MillstoneCraneWinchMaker.ironStock=18; MillstoneCraneWinchMaker.bronzeStock=14; MillstoneCraneWinchMaker.woodStock=10; MillstoneCraneWinchMaker.leatherStock=8; MillstoneCraneWinchMaker.silverStock=8; MillstoneCraneWinchMaker.goldStock=6; MillstoneCraneWinchMaker.jewelStock=4; MillstoneCraneWinchMaker.pearlStock=4; MillstoneCraneWinchMaker.productStock={}; MillstoneCraneWinchMaker.buildings={}; MillstoneCraneWinchMaker.maker=nil; MillstoneCraneWinchMaker.activeMaking={}; MillstoneCraneWinchMaker.totalProducts=0; MillstoneCraneWinchMaker.dayTimer=0; print("[MillstoneCraneWinchMaker] Royal Millstone Crane Winch Maker System initialized (6 products, 4 buildings)") end
function MillstoneCraneWinchMaker.hireMaker(n,s) s=s or math.random(55,90); local c=585+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; MillstoneCraneWinchMaker.maker={name=n or ("Vitjar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Vitjar najet: %s (spretnost: %d)",MillstoneCraneWinchMaker.maker.name,s),"success") end; return true end
function MillstoneCraneWinchMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function MillstoneCraneWinchMaker.build(id) local ok,e=MillstoneCraneWinchMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(MillstoneCraneWinchMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
