function MillstoneCraneWinchMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and MillstoneCraneWinchMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and MillstoneCraneWinchMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and MillstoneCraneWinchMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and MillstoneCraneWinchMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and MillstoneCraneWinchMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and MillstoneCraneWinchMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and MillstoneCraneWinchMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and MillstoneCraneWinchMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #MillstoneCraneWinchMaker.buildings==0 then return false,"Potrebna vitezna delavnica" end; if not MillstoneCraneWinchMaker.maker then return false,"Potreben vitjar" end; return true end
function MillstoneCraneWinchMaker.make(pt,qty) qty=qty or 1; local ok,e=MillstoneCraneWinchMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then MillstoneCraneWinchMaker.ironStock=MillstoneCraneWinchMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then MillstoneCraneWinchMaker.bronzeStock=MillstoneCraneWinchMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then MillstoneCraneWinchMaker.woodStock=MillstoneCraneWinchMaker.woodStock-d.woodCost*qty end; if d.leatherCost then MillstoneCraneWinchMaker.leatherStock=MillstoneCraneWinchMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then MillstoneCraneWinchMaker.silverStock=MillstoneCraneWinchMaker.silverStock-d.silverCost*qty end; if d.goldCost then MillstoneCraneWinchMaker.goldStock=MillstoneCraneWinchMaker.goldStock-d.goldCost*qty end; if d.jewelCost then MillstoneCraneWinchMaker.jewelStock=MillstoneCraneWinchMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then MillstoneCraneWinchMaker.pearlStock=MillstoneCraneWinchMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if MillstoneCraneWinchMaker.maker then t=math.max(1,t-math.floor(MillstoneCraneWinchMaker.maker.skill/13)) end; table.insert(MillstoneCraneWinchMaker.activeMaking,{id="millstonecranewinch_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function MillstoneCraneWinchMaker.completeMaking(m) local q=1.0+(MillstoneCraneWinchMaker.getQualityBonus()/100); if MillstoneCraneWinchMaker.maker then q=q+(MillstoneCraneWinchMaker.maker.skill/140) end; q=math.min(2.5,q); MillstoneCraneWinchMaker.productStock[m.productType]=(MillstoneCraneWinchMaker.productStock[m.productType] or 0)+m.quantity; MillstoneCraneWinchMaker.totalProducts=MillstoneCraneWinchMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if MillstoneCraneWinchMaker.maker then MillstoneCraneWinchMaker.maker.itemsMade=MillstoneCraneWinchMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then MillstoneCraneWinchMaker.maker.skill=math.min(100,MillstoneCraneWinchMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Vitek izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"millstonecranewinch.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function MillstoneCraneWinchMaker.update(dt) if not _G.state then return end; MillstoneCraneWinchMaker.dayTimer=MillstoneCraneWinchMaker.dayTimer+dt; if MillstoneCraneWinchMaker.dayTimer>=30 then MillstoneCraneWinchMaker.dayTimer=0; for i=#MillstoneCraneWinchMaker.activeMaking,1,-1 do local m=MillstoneCraneWinchMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then MillstoneCraneWinchMaker.completeMaking(m); table.remove(MillstoneCraneWinchMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(MillstoneCraneWinchMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if MillstoneCraneWinchMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
